{"actions":[{"action":"success_contract","data":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet 127.0.0.1 6665 connects to a login prompt, and leave it running until ready.","required_artifacts":["A running QEMU process booted from /app/alpine.iso","A listening telnet-accessible service on 127.0.0.1:6665"],"required_behaviors":["QEMU starts successfully in the background","Port 6665 on localhost accepts telnet connections","Telnet shows a login prompt before any login is entered","The VM remains running after readiness is reached"],"known_invalid_patterns":["File existence alone","Compilation or non-empty output alone","A boot attempt that does not expose telnet on 127.0.0.1:6665","A prompt shown only in logs without a reachable telnet service"],"verification_plan":["Inspect available tools and filesystem for the ISO and QEMU availability","Start QEMU with a serial/console configuration that exposes a telnet server on localhost:6665","Block until the telnet port is reachable and the login prompt is observable","Record receipt-backed evidence for the running process and reachable prompt"],"finalization_evidence_required":["Receipt showing QEMU launch command succeeded in background","Receipt showing 127.0.0.1:6665 is reachable","Receipt showing telnet session reaches a login prompt"],"notes":["Prerequisites like QEMU being installed are not success by themselves; they only inform implementation."]}}] }
{"actions":[{"action":"plan_update","data":{"objective":"Start /app/alpine.iso in QEMU in the background so that telnet 127.0.0.1:6665 connects to a login prompt, and leave it running until ready.","evidence":[],"current_focus":"Discover available tooling and confirm the ISO path plus QEMU invocation options for telnet console exposure.","implementation_approach":["Inspect filesystem and tool availability.","Determine whether qemu-system-* and telnet/nc are present.","Launch QEMU with a serial console redirected to a telnet server on localhost:6665 or equivalent.","Keep the VM running in the background."],"validation_strategy":["Use receipt-backed command output to confirm the process started.","Probe localhost:6665 until it accepts connections.","Confirm the telnet session displays a login prompt."],"verification_test_strategy":["Prefer direct telnet connection evidence over indirect logs.","Avoid treating boot messages alone as success."],"known_bad_behavior":["Starting QEMU without exposing a telnet-accessible console.","Stopping the VM after readiness.","Using a different port or interface than 127.0.0.1:6665."],"evidence_gaps":["Need confirmation that /app/alpine.iso exists and is bootable.","Need confirmation that QEMU is installed and which binary to use.","Need evidence of a reachable login prompt over telnet."],"risks":["The environment may lack QEMU or networking tools.","The ISO may require specific boot parameters or console settings."],"next_steps":["Inspect /app and PATH for qemu binaries.","If present, launch QEMU in background with telnet console.","Probe readiness and capture receipts."],"finalization_evidence_required":["Receipt showing QEMU launch command succeeded in background","Receipt showing 127.0.0.1:6665 is reachable","Receipt showing telnet session reaches a login prompt"]}}]}
{"actions":[{"action":"raw_bash","data":"set -e
ls -l /app || true
command -v qemu-system-x86_64 || command -v qemu-system-i386 || command -v qemu-system-aarch64 || true
command -v telnet || command -v nc || true
"}]}
